def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
        char = board[row][col]
        if char == 'g':
            board[row][col] = 'N'
            if col > 0 and board[row][col-1] == 'g':
                board[row][col-1] = 'N'
            if col < 63 and board[row][col+1] == 'g':
                board[row][col+1] = 'N'
        elif char == 'b':
            board[row][col] = 'N'
            if col > 0 and board[row][col-1] == 'b':
                board[row][col-1] = 'N'
            if col < 63 and board[row][col+1] == 'b':
                board[row][col+1] = 'N'
        else:
            board[row][col] = 'W'
            if col > 0 and board[row][col-1] == 'W':
                board[row][col-1] = 'G'
            if col < 63 and board[row][col+1] == 'W':
                board[row][col+1] = 'G'
    return ["".join(row) for row in board]
